/*
 * VN01 — preset importe de Lightroom.
 *
 * GENERE PAR `scripts/import-lightroom-preset.mjs`. Ne pas editer a la main:
 * relancer l'import si le preset change dans Lightroom.
 *
 * La couleur vient d'une Hald CLUT passee dans Lightroom: ce n'est pas une
 * approximation des calculs d'Adobe, c'est leur resultat mesure sur toute la
 * grille RVB (ecart moyen a l'identite: 19.6/255, max 171/255).
 *
 * Reglages lus dans le .xmp ou releves dans Lightroom:
 *   - blancs -36
 *   - noirs -54
 *   - grain +22
 *   - taille du grain +17
 *   - cassure du grain +50
 *   - saturation -6
 *   - mélangeur — red T+6/S-10/L-25, orange T-13/S-14/L-10, yellow T+12/S-22, green T+34/S-37, aqua T+21/S-13, blue T+15/S+6/L-12, purple T+10/S+4, magenta T+25/S-20
 *   - courbe maître 5 points
 *   - courbes RVB par canal
 * Reglages hors LUT effectivement importes:
 *   - grain: 22
 *   - grainSize: 17
 *   - grainRoughness: 50
 *
 * Source Hald : hald-clut-neutre-niveau8-bloc4.png (niveau 8, cube 64)
 * Importe le  : 2026-08-31
 */

import { lutFromBase64 } from '../haldClut.js';

const LUT_BASE64 = '';

let cached = null;

export const preset = {
    id: 'vn01',
    label: "VN01",
    collection: {"id":"vintage","label":"Vintage"},
    hint: "Preset importé de Lightroom",
    description: "Capturé depuis Lightroom par table de conversion complète. Réglages : blancs -36 · noirs -54 · grain +22 · taille du grain +17 · cassure du grain +50 · saturation -6 · mélangeur — red T+6/S-10/L-25, orange T-13/S-14/L-10, yellow T+12/S-22, green T+34/S-37, aqua T+21/S-13, blue T+15/S+6/L-12, purple T+10/S+4, magenta T+25/S-20 · courbe maître 5 points · courbes RVB par canal.",
    bestFor: "à définir après essai sur tes photos",
    avoidFor: "photos déjà fortement filtrées",
    recommendedIntensity: 100,
    /* Reglages que la table ne peut pas porter (ils dependent des pixels
       voisins ou de la position dans l'image), lus dans le .xmp. */
    spatialFilters: {"grain":22,"grainSize":17,"grainRoughness":50},
    /* La table elle-meme, decodee au premier usage. */
    getLut() {
        if (!cached) cached = lutFromBase64(LUT_BASE64);
        return cached;
    },
};

export default preset;
